std::vector<int> TopologicalSort(const std::vector<std::vector<int>>& graph, bool& isUnique)
{
	// 各頂点の入次数を管理する配列
	std::vector<int> indegrees(graph.size());

	// 入次数を計算する
	for (const auto& v : graph)
	{
		for (const auto& next : v)
		{
			++indegrees[next];
		}
	}

	// 入次数が 0 の頂点を管理するキュー
	std::queue<int> q;

	// 現時点で入次数が 0 の頂点をすべてキューに追加する
	for (int i = 0; i < static_cast<int>(graph.size()); ++i)
	{
		if (indegrees[i] == 0)
		{
			q.push(i);
		}
	}

	// 結果（トポロジカル順序）を格納する配列
	std::vector<int> result;

	isUnique = true;

	while (!q.empty())
	{
		// キューに 2 つ以上要素がある場合、順序が一意にはならない
		if (1 < q.size())
		{
			isUnique = false;
		}

		// 入次数が 0 の頂点を 1 つ取り出す
		const int current = q.front();
		q.pop();

		// トポロジカル順序に追加する
		result.push_back(current);

		// その頂点から出る各辺について
		for (const auto& next : graph[current])
		{
			// その先の頂点の入次数を減らし、新たに 0 になったらキューに追加する
			if (--indegrees[next] == 0)
			{
				q.push(next);
			}
		}
	}

	// 閉路が存在する（頂点をすべて処理できていない）場合
	if (result.size() < graph.size())
	{
		// 空の配列を返す
		return{};
	}

	return result;
}

int main()
{
	// N 個のチーム, M 個の対戦結果
	int N, M;
	std::cin >> N >> M;

	// 隣接リストを構築する
	// s が t に勝ったなら、s から t に辺を張る
	std::vector<std::vector<int>> graph(N);
	for (int i = 0; i < M; ++i)
	{
		int s, t;
		std::cin >> s >> t;
		--s; --t;
		graph[s].push_back(t);
	}

	// トポロジカル順序が一意かどうか
	bool isUnique = true;

	// トポロジカル順序
	const std::vector<int> result = TopologicalSort(graph, isUnique);

	for (const auto& v : result)
	{
		std::cout << (v + 1) << '\n';
	}

	// トポロジカル順序が一意かどうかを出力する
	if (isUnique)
	{
		std::cout << "0\n";
	}
	else
	{
		std::cout << "1\n";
	}
}
